  const [crop, setCrop] = useState('Rice (Paddy)');
  const [selectedState, setSelectedState] = useState('Punjab');
  const [isLoading, setIsLoading] = useState(false);
  const [result, setResult] = useState<FarmPlanResult | null>(null);

